function inferType(enunciado, formula, subtema) {
  const text = `${enunciado} ${subtema}`.toLowerCase();
  if (text.includes("unidad") || text.includes("si")) {
    if (text.includes("unidad")) return "unidades";
  }
  if (/[0-9]/.test(text) && (text.includes("vale") || text.includes("calcula") || text.includes("rendimiento") || text.includes("distancia"))) return "calculo corto";
  if (text.includes("duplica") || text.includes("aumenta") || text.includes("disminuye") || text.includes("depende")) return "interpretacion fisica";
  if (text.includes("error") || text.includes("trampa") || text.includes("confundir")) return "trampa tipica";
  if (formula) return "formula";
  if (text.includes("ocurre") || text.includes("implica") || text.includes("porque")) return "caso conceptual";
  return "teoria";
}

function defaultTheory(tema, subtema, formula) {
  const base = THEORY_BY_SUBTOPIC[subtema] || "Identifica primero la magnitud fisica preguntada, las condiciones que permanecen constantes y las unidades del Sistema Internacional. En test suele haber distractores por signo, proporcionalidad o confusion entre magnitudes parecidas.";
  const formulaNote = formula ? " Puede haber una formula relacionada, pero antes de sustituir conviene pensar que magnitudes cambian y cuales se mantienen constantes." : "";
  return `${base}${formulaNote}`;
}

const q = (tema, subtema, dificultad, enunciado, opciones, correcta, explicacion, formula = "", tipo = "", teoria = "") => ({
  id: nextId++,
  tema,
  subtema,
  dificultad,
  enunciado,
  opciones,
  correcta,
  explicacion,
  teoria: teoria || defaultTheory(tema, subtema, formula),
  formula: formula ? toDisplayLatex(formula) : "",
  tipo: tipo || inferType(enunciado, formula, subtema),
});

