function balancedQuestion(question) {
  const target = (question.id - 1) % 4;
  const shift = (target - question.correcta + 4) % 4;
  if (shift === 0) return question;
  const opciones = question.opciones.map((_, index) => question.opciones[(index - shift + 4) % 4]);
  return {
    ...question,
    opciones,
    correcta: target,
  };
}

export const questions = rawQuestions.map(balancedQuestion);
export const topics = [...new Set(questions.map((question) => question.tema))];
export const difficulties = ["facil", "media", "dificil"];
export const questionTypes = [
  "teoria",
  "formula",
  "calculo corto",
  "unidades",
  "interpretacion fisica",
  "caso conceptual",
  "trampa tipica",
];
